82				args = append(args, id)
83			}
84		}
85		if v := find.UID; v != nil {
86			where, args = append(where, "`memo`.`uid` = ?"), append(args, *v)
87		}
88		if len(find.UIDList) > 0 {
89			placeholders := make([]string, 0, len(find.UIDList))
90			for range find.UIDList {
91				placeholders = append(placeholders, "?")
92			}
93			where = append(where, "`memo`.`uid` IN ("+strings.Join(placeholders, ",")+")")
94			for _, uid := range find.UIDList {
95				args = append(args, uid)
96			}
97		}
98		if v := find.CreatorID; v != nil {
99			where, args = append(where, "`memo`.`creator_id` = ?"), append(args, *v)
100		}
101		if v := find.RowStatus; v != nil {
102			where, args = append(where, "`memo`.`row_status` = ?"), append(args, *v)
103		}
104		if v := find.VisibilityList; len(v) != 0 {
105			placeholder := []string{}
106			for _, visibility := range v {
107				placeholder = append(placeholder, "?")
108				args = append(args, visibility.String())
109			}
110			where = append(where, fmt.Sprintf("`memo`.`visibility` in (%s)", strings.Join(placeholder, ",")))
111		}
112		if find.ExcludeComments {
113			having = append(having, "`parent_uid` IS NULL")
114		}
115	
116		order := "DESC"
117		if find.OrderByTimeAsc {
118			order = "ASC"
119		}
120		orderBy := []string{}
121		if find.OrderByPinned {
122			orderBy = append(orderBy, "`pinned` DESC")
123		}
124		if find.OrderByUpdatedTs {
125			orderBy = append(orderBy, "`updated_ts` "+order)
126		} else {
127			orderBy = append(orderBy, "`created_ts` "+order)
128		}
129		// Add id as final tie-breaker
130		orderBy = append(orderBy, "`id` DESC")
131		fields := []string{
132			"`memo`.`id` AS `id`",
133			"`memo`.`uid` AS `uid`",
134			"`memo`.`creator_id` AS `creator_id`",
135			"UNIX_TIMESTAMP(`memo`.`created_ts`) AS `created_ts`",
136			"UNIX_TIMESTAMP(`memo`.`updated_ts`) AS `updated_ts`",
137			"`memo`.`row_status` AS `row_status`",
138			"`memo`.`visibility` AS `visibility`",
139			"`memo`.`pinned` AS `pinned`",
140			"`memo`.`payload` AS `payload`",
141			"CASE WHEN `parent_memo`.`uid` IS NOT NULL THEN `parent_memo`.`uid` ELSE NULL END AS `parent_uid`",
142		}
143		if !find.ExcludeContent {
144			fields = append(fields, "`memo`.`content` AS `content`")
145		}
146	
147		query := "SELECT " + strings.Join(fields, ", ") + " FROM `memo`" + " " +
148			"LEFT JOIN `user` AS `memo_creator` ON `memo`.`creator_id` = `memo_creator`.`id`" + " " +
149			"LEFT JOIN `memo_relation` ON `memo`.`id` = `memo_relation`.`memo_id` AND `memo_relation`.`type` = 'COMMENT'" + " " +
150			"LEFT JOIN `memo` AS `parent_memo` ON `memo_relation`.`related_memo_id` = `parent_memo`.`id`" + " " +
151			"WHERE " + strings.Join(where, " AND ") + " " +
152			"HAVING " + strings.Join(having, " AND ") + " " +
153			"ORDER BY " + strings.Join(orderBy, ", ")
154		if find.Limit != nil {
155			query = fmt.Sprintf("%s LIMIT %d", query, *find.Limit)
156			if find.Offset != nil {
157				query = fmt.Sprintf("%s OFFSET %d", query, *find.Offset)
158			}
159		}
160	
161		rows, err := d.db.QueryContext(ctx, query, args...)
162		if err != nil {
163			return nil, err
164		}
165		defer rows.Close()
166	
167		list := make([]*store.Memo, 0)
168		for rows.Next() {
169			var memo store.Memo
170			var payloadBytes []byte
171			dests := []any{
172				&memo.ID,
173				&memo.UID,
174				&memo.CreatorID,
175				&memo.CreatedTs,
176				&memo.UpdatedTs,
177				&memo.RowStatus,
178				&memo.Visibility,
179				&memo.Pinned,
180				&payloadBytes,
181				&memo.ParentUID,
182			}
183			if !find.ExcludeContent {
184				dests = append(dests, &memo.Content)
185			}
186			if err := rows.Scan(dests...); err != nil {
187				return nil, err
188			}
189			payload := &storepb.MemoPayload{}
190			if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
191				return nil, errors.Wrap(err, "failed to unmarshal payload")
192			}
193			memo.Payload = payload
194			list = append(list, &memo)
195		}
196	
197		if err := rows.Err(); err != nil {
198			return nil, err
199		}
200	
201		return list, nil
202	}
203	
204	func (d *DB) GetMemo(ctx context.Context, find *store.FindMemo) (*store.Memo, error) {
205		list, err := d.ListMemos(ctx, find)
206		if err != nil {
207			return nil, err
208		}
209		if len(list) == 0 {
210			return nil, nil
211		}
212	
213		memo := list[0]
214		return memo, nil
215	}
216	
217	func (d *DB) UpdateMemo(ctx context.Context, update *store.UpdateMemo) error {
218		set, args := []string{}, []any{}
219		if v := update.UID; v != nil {
220			set, args = append(set, "`uid` = ?"), append(args, *v)
221		}
222		if v := update.CreatedTs; v != nil {
223			set, args = append(set, "`created_ts` = FROM_UNIXTIME(?)"), append(args, *v)
224		}
225		if v := update.UpdatedTs; v != nil {
226			set, args = append(set, "`updated_ts` = FROM_UNIXTIME(?)"), append(args, *v)
227		}
228		if v := update.RowStatus; v != nil {
229			set, args = append(set, "`row_status` = ?"), append(args, *v)
230		}
231		if v := update.Content; v != nil {
232			set, args = append(set, "`content` = ?"), append(args, *v)
233		}
234		if v := update.Visibility; v != nil {
235			set, args = append(set, "`visibility` = ?"), append(args, *v)
236		}
237		if v := update.Pinned; v != nil {
238			set, args = append(set, "`pinned` = ?"), append(args, *v)
239		}
240		if v := update.Payload; v != nil {
241			payloadBytes, err := protojson.Marshal(v)
242			if err != nil {
243				return err
244			}
245			set, args = append(set, "`payload` = ?"), append(args, string(payloadBytes))
246		}
247		if len(set) == 0 {
248			return nil
249		}
250		args = append(args, update.ID)
251	
252		stmt := "UPDATE `memo` SET " + strings.Join(set, ", ") + " WHERE `id` = ?"
253		if _, err := d.db.ExecContext(ctx, stmt, args...); err != nil {
254			return err
255		}
256		return nil
257	}
258	
259	func (d *DB) DeleteMemo(ctx context.Context, delete *store.DeleteMemo) error {
260		where, args := []string{"`id` = ?"}, []any{delete.ID}
261		stmt := "DELETE FROM `memo` WHERE " + strings.Join(where, " AND ")
262		result, err := d.db.ExecContext(ctx, stmt, args...)
263		if err != nil {
264			return err
265		}
266		if _, err := result.RowsAffected(); err != nil {
267			return err
268		}
269		return nil
270	}
