16	func (s *APIV1Service) SetMemoRelations(ctx context.Context, request *v1pb.SetMemoRelationsRequest) (*emptypb.Empty, error) {
17		user, err := s.fetchCurrentUser(ctx)
18		if err != nil {
19			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
20		}
21		if user == nil {
22			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
23		}
24		memoUID, err := ExtractMemoUIDFromName(request.Name)
25		if err != nil {
26			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
27		}
28		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
29		if err != nil {
30			return nil, status.Errorf(codes.Internal, "failed to get memo")
31		}
32		if memo == nil {
33			return nil, status.Errorf(codes.NotFound, "memo not found")
34		}
35		if memo.CreatorID != user.ID && !isSuperUser(user) {
36			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
37		}
38		if err := s.setMemoRelationsInternal(ctx, memo, request.Relations); err != nil {
39			return nil, err
40		}
41		if err := s.touchMemoUpdatedTimestamp(ctx, memo.ID); err != nil {
42			return nil, err
43		}
44		updatedMemo, parentMemo, memoMessage, err := s.buildUpdatedMemoState(ctx, memo.ID)
45		if err != nil {
46			return nil, status.Errorf(codes.Internal, "failed to build updated memo state")
47		}
48		s.dispatchMemoUpdatedSideEffects(ctx, updatedMemo, parentMemo, memoMessage)
49	
50		return &emptypb.Empty{}, nil
51	}
52	
53	func (s *APIV1Service) setMemoRelationsInternal(ctx context.Context, memo *store.Memo, relations []*v1pb.MemoRelation) error {
54		referenceType := store.MemoRelationReference
55		// Delete all reference relations first.
56		if err := s.Store.DeleteMemoRelation(ctx, &store.DeleteMemoRelation{
57			MemoID: &memo.ID,
58			Type:   &referenceType,
59		}); err != nil {
60			return status.Errorf(codes.Internal, "failed to delete memo relation")
61		}
62	
63		for _, relation := range relations {
64			// Ignore reflexive relations.
65			if buildMemoName(memo.UID) == relation.RelatedMemo.Name {
66				continue
67			}
68			// Ignore comment relations as there's no need to update a comment's relation.
69			// Inserting/Deleting a comment is handled elsewhere.
70			if relation.Type == v1pb.MemoRelation_COMMENT {
71				continue
72			}
73			relatedMemoUID, err := ExtractMemoUIDFromName(relation.RelatedMemo.Name)
74			if err != nil {
75				return status.Errorf(codes.InvalidArgument, "invalid related memo name: %v", err)
76			}
77			relatedMemo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &relatedMemoUID})
78			if err != nil {
79				return status.Errorf(codes.Internal, "failed to get related memo")
80			}
81			if _, err := s.Store.UpsertMemoRelation(ctx, &store.MemoRelation{
82				MemoID:        memo.ID,
83				RelatedMemoID: relatedMemo.ID,
84				Type:          convertMemoRelationTypeToStore(relation.Type),
85			}); err != nil {
86				return status.Errorf(codes.Internal, "failed to upsert memo relation")
87			}
88		}
89	
90		return nil
91	}
92	
93	func (s *APIV1Service) ListMemoRelations(ctx context.Context, request *v1pb.ListMemoRelationsRequest) (*v1pb.ListMemoRelationsResponse, error) {
94		memoUID, err := ExtractMemoUIDFromName(request.Name)
95		if err != nil {
96			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
97		}
98		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
99		if err != nil {
100			return nil, status.Errorf(codes.Internal, "failed to get memo")
101		}
102	
103		currentUser, err := s.fetchCurrentUser(ctx)
104		if err != nil {
105			return nil, status.Errorf(codes.Internal, "failed to get user")
106		}
107		var memoFilter string
108		if currentUser == nil {
109			memoFilter = `visibility == "PUBLIC"`
110		} else {
111			memoFilter = fmt.Sprintf(`creator_id == %d || visibility in ["PUBLIC", "PROTECTED"]`, currentUser.ID)
112		}
113		relationList := []*v1pb.MemoRelation{}
114		tempList, err := s.Store.ListMemoRelations(ctx, &store.FindMemoRelation{
115			MemoID:     &memo.ID,
116			MemoFilter: &memoFilter,
117		})
118		if err != nil {
119			return nil, status.Errorf(codes.Internal, "failed to list memo relations: %v", err)
120		}
121		for _, raw := range tempList {
122			relation, err := s.convertMemoRelationFromStore(ctx, raw)
123			if err != nil {
124				return nil, status.Errorf(codes.Internal, "failed to convert memo relation")
125			}
126			relationList = append(relationList, relation)
127		}
128		tempList, err = s.Store.ListMemoRelations(ctx, &store.FindMemoRelation{
129			RelatedMemoID: &memo.ID,
130			MemoFilter:    &memoFilter,
131		})
132		if err != nil {
133			return nil, status.Errorf(codes.Internal, "failed to list related memo relations: %v", err)
134		}
135		for _, raw := range tempList {
136			relation, err := s.convertMemoRelationFromStore(ctx, raw)
137			if err != nil {
138				return nil, status.Errorf(codes.Internal, "failed to convert memo relation")
139			}
140			relationList = append(relationList, relation)
141		}
142	
143		response := &v1pb.ListMemoRelationsResponse{
144			Relations: relationList,
145		}
146		return response, nil
147	}
148	
149	func (s *APIV1Service) convertMemoRelationFromStore(ctx context.Context, memoRelation *store.MemoRelation) (*v1pb.MemoRelation, error) {
150		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &memoRelation.MemoID})
151		if err != nil {
152			return nil, status.Errorf(codes.Internal, "failed to get memo: %v", err)
153		}
154		memoSnippet, err := s.getMemoContentSnippet(memo.Content)
155		if err != nil {
156			return nil, errors.Wrap(err, "failed to get memo content snippet")
157		}
158		relatedMemo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &memoRelation.RelatedMemoID})
159		if err != nil {
160			return nil, status.Errorf(codes.Internal, "failed to get related memo: %v", err)
161		}
162		relatedMemoSnippet, err := s.getMemoContentSnippet(relatedMemo.Content)
163		if err != nil {
164			return nil, errors.Wrap(err, "failed to get related memo content snippet")
165		}
166		return &v1pb.MemoRelation{
167			Memo: &v1pb.MemoRelation_Memo{
168				Name:    fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID),
169				Snippet: memoSnippet,
170			},
171			RelatedMemo: &v1pb.MemoRelation_Memo{
172				Name:    fmt.Sprintf("%s%s", MemoNamePrefix, relatedMemo.UID),
173				Snippet: relatedMemoSnippet,
174			},
175			Type: convertMemoRelationTypeFromStore(memoRelation.Type),
176		}, nil
177	}
178	
179	func convertMemoRelationTypeFromStore(relationType store.MemoRelationType) v1pb.MemoRelation_Type {
180		switch relationType {
181		case store.MemoRelationReference:
182			return v1pb.MemoRelation_REFERENCE
183		case store.MemoRelationComment:
184			return v1pb.MemoRelation_COMMENT
185		default:
186			return v1pb.MemoRelation_TYPE_UNSPECIFIED
187		}
188	}
189	
190	func convertMemoRelationTypeToStore(relationType v1pb.MemoRelation_Type) store.MemoRelationType {
191		switch relationType {
192		case v1pb.MemoRelation_COMMENT:
193			return store.MemoRelationComment
194		default:
195			return store.MemoRelationReference
196		}
197	}
